const WebSocket = require('ws');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const UPLOAD_DIR = '/tmp/uploads';
const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32);
const MAX_FILE_SIZE = 10 * 1024 * 1024;

class NonceStore {
  constructor(maxAge = 300000) {
    this.nonces = new Map();
    this.maxAge = maxAge;
    setInterval(() => this._cleanup(), 60000);
  }

  _cleanup() {
    const now = Date.now();
    for (const [nonce, ts] of this.nonces) {
      if (now - ts > this.maxAge) {
        this.nonces.delete(nonce);
      }
    }
  }

  has(nonce) {
    return this.nonces.has(nonce);
  }

  add(nonce) {
    this.nonces.set(nonce, Date.now());
  }
}

const nonceStore = new NonceStore();

function verifySignature(payload, signature, timestamp, nonce) {
  const now = Math.floor(Date.now() / 1000);
  const ts = parseInt(timestamp, 10);

  if (isNaN(ts) || Math.abs(now - ts) > 300) {
    return { valid: false, reason: 'timestamp_expired' };
  }

  if (!nonce || nonce.length < 16) {
    return { valid: false, reason: 'invalid_nonce' };
  }

  const signingString = `${timestamp}.${nonce}.${payload}`;
  const expectedSig = crypto.createHmac('sha256', HMAC_SECRET)
    .update(signingString)
    .digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expectedSig, 'hex'))) {
    return { valid: false, reason: 'signature_mismatch' };
  }

  // Check nonce reuse AFTER signature verification succeeds
  if (nonceStore.has(nonce)) {
    return { valid: false, reason: 'nonce_reused' };
  }

  return { valid: true };
}

function processUpload(metadata, fileData) {
  const sanitizedName = path.basename(metadata.filename).replace(/[^a-zA-Z0-9._-]/g, '_');
  const destPath = path.join(UPLOAD_DIR, sanitizedName);

  if (fileData.length > MAX_FILE_SIZE) {
    return { success: false, error: 'file_too_large' };
  }

  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
  fs.writeFileSync(destPath, fileData);
  return { success: true, path: destPath, size: fileData.length };
}

function handleMessage(ws, message) {
  try {
    const envelope = JSON.parse(message.toString('utf8'));

    if (!envelope.signature || !envelope.timestamp || !envelope.nonce || !envelope.payload) {
      ws.send(JSON.stringify({ error: 'missing_fields' }));
      return;
    }

    const payloadStr = JSON.stringify(envelope.payload);
    const verification = verifySignature(
      payloadStr,
      envelope.signature,
      envelope.timestamp,
      envelope.nonce
    );

    if (!verification.valid) {
      ws.send(JSON.stringify({ error: verification.reason }));
      return;
    }

    // Record nonce after successful processing begins
    nonceStore.add(envelope.nonce);

    const { action } = envelope.payload;

    if (action === 'upload') {
      const fileData = Buffer.from(envelope.payload.data, 'base64');
      const result = processUpload(envelope.payload.metadata, fileData);
      ws.send(JSON.stringify(result));
    } else if (action === 'list') {
      const files = fs.existsSync(UPLOAD_DIR) ? fs.readdirSync(UPLOAD_DIR) : [];
      ws.send(JSON.stringify({ files }));
    } else {
      ws.send(JSON.stringify({ error: 'unknown_action' }));
    }
  } catch (err) {
    ws.send(JSON.stringify({ error: 'parse_error', detail: err.message }));
  }
}

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws, req) => {
  console.log(`Client connected from ${req.socket.remoteAddress}`);

  ws.on('message', (message) => {
    handleMessage(ws, message);
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});

console.log('WebSocket upload server running on port 8080');

module.exports = { verifySignature, processUpload, handleMessage, nonceStore };
